-- US TWO: additive catalog migration, leaves the 67 existing quest cards untouched.
ALTER TABLE public.us_quest_catalog ADD COLUMN IF NOT EXISTS estimated_cost_eur integer NOT NULL DEFAULT 0;
ALTER TABLE public.us_quest_catalog DROP CONSTRAINT IF EXISTS us_quest_catalog_estimated_cost_check;
ALTER TABLE public.us_quest_catalog ADD CONSTRAINT us_quest_catalog_estimated_cost_check CHECK (estimated_cost_eur BETWEEN 0 AND 500);
